func (g StudioOutputs) Get(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_outputs", "get", p)
}

// Show: Same as `get` plus up to 4 small preview images (max 8 items per call; previews total ≤72KB, those that do not fit are listed in `previews_skipped`, download links still returned). Scopes: read. Flags: image.
func (g StudioOutputs) Show(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_outputs", "show", p)
}

// StudioStoryboard wraps the studio_storyboard tool — Storyboard player. Animated storyboard: plays the storyboard inside the conversation with an embedded player and waits for the user's approval before rendering. Flow: `studio_create.storyboard`, then `draw`, then `show`, then the user approves, then `approve`, then `studio.storyboard_video`. Rendering actions check that the storyboard has been approved.
type StudioStoryboard struct{ c *Client }

// Show: Play the animated storyboard in the conversation. args `{version?, panel?, autoplay?}`; returns `shots[]` and a signed `sheet_url`; call again to jump to a shot. Scopes: read.
func (g StudioStoryboard) Show(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_storyboard", "show", p)
}

// Approve: Destructive (needs `confirm: true`): record the user's approval of this version; only after they said approve. args `{video_style?}`: realistic (default), film, commercial, anime, animation3d, match. Scopes: edit. Flags: confirm.
func (g StudioStoryboard) Approve(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_storyboard", "approve", p)
}

// Draw: Paid: draw an undrawn storyboard version as one image; call only when the user explicitly asks. args `{model?, seed?, draw_style?, arrows?}` as in `studio_create.storyboard_draw`. Scopes: spend. Flags: paid.
func (g StudioStoryboard) Draw(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_storyboard", "draw", p)
}

// Revise: Revise the storyboard in plain language (free, creates a new version that must be redrawn with `draw`). args `{instruction}`; without it a new version is drawn unchanged. Scopes: edit.
func (g StudioStoryboard) Revise(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_storyboard", "revise", p)
}

// StudioCast wraps the studio_cast tool — Pick a character. Character selection: before a storyboard or render, ask the user which character from the character library should be the lead. Hosts that support MCP Apps show a character card to tap; other hosts give the user a `pick_url` web page, or the user answers with a number and you call `choose`. After picking, pass `args.cast_pick:<pick_id>` to the storyboard or render call.
type StudioCast struct{ c *Client }

// Pick: Open a character picker (all ready characters, or those in `args.ids`); returns `pick_id`, `pick_url`, numbered candidates and thumbnails. Scopes: read.
func (g StudioCast) Pick(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_cast", "pick", p)
}

// Show: Show the picker again (the `pick_id` returned by `needs_cast`). args `{pick_id}`. Scopes: read.
func (g StudioCast) Show(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_cast", "show", p)
}

// Choose: Record which character the user picked (the embedded card calls this itself; if the user answers a number or name in conversation, you call it). args `{pick_id, ids?|ns?|none?}`. Scopes: edit.
func (g StudioCast) Choose(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_cast", "choose", p)
}

// Thumbs: Get candidate character thumbnails (used by the picker card). args `{pick_id}`. Scopes: read.
func (g StudioCast) Thumbs(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_cast", "thumbs", p)
}

// Result: Check whether the user has picked (use after a web or embedded pick). args `{pick_id}`; returns `status` waiting or chosen, and `refs`. Scopes: read.
func (g StudioCast) Result(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_cast", "result", p)
}

// StudioConfirm wraps the studio_confirm tool — Confirm a spend. Approval cards for spending and permissions. When an action returns `needs_confirmation` + `confirm_token` (or `needs_permission` + `permission_token`), call `show` to display the card, then call `wait` (up to 50 seconds per call; call again while `open`). On `approved` repeat the original call with identical args plus the token; on `declined` do not proceed. With `approval: "user"` (only when the key's owner turned on page approval) only the user can approve, on the `approve_url` page on AlgoHash while signed in; a yes in chat does not count and `decide` cannot approve. Hosts without cards should give the user the `approve_url`.
type StudioConfirm struct{ c *Client }

// Show: Show a quote approval card (`confirm_token`) or permission card (`permission_token`); does not charge or consume the token. args `{confirm_token|permission_token, summary?, what?}`. Scopes: read.
func (g StudioConfirm) Show(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_confirm", "show", p)
}

// Wait: Call right after `show` (or after giving the user the `approve_url`) to wait for the user's decision (up to 50 s; `open` means undecided, call again). args `{confirm_token|permission_token, timeout_sec?}`. Scopes: read.
func (g StudioConfirm) Wait(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_confirm", "wait", p)
}

// StudioBrowse wraps the studio_browse tool — Browse your library. Library card: shows the user's characters, scenes, props and works in the conversation with thumbnails and search; the user picks items and taps use-as-reference, and the picks come back as conversation messages (`avatars/<id>`, `output_id <id>`) to put in `refs`. Hosts without MCP Apps read the text list instead.
type StudioBrowse struct{ c *Client }

// Show: Show the library card. args `{pillar?: avatars|environments|items|outputs}`; returns the list (latest 60). Scopes: read.
