func (g StudioPaper) Delete(ctx context.Context, p Params) (*ToolResult, error) {
	return g.c.CallAction(ctx, "studio_paper", "delete", p)
}

// StudioClient is a typed client for the studio MCP server (https://console.algohash.ai/mcp/studio).
type StudioClient struct {
	*Client
	Core       StudioCore
	Project    StudioProject
	Shots      StudioShots
	Layers     StudioLayers
	Audio      StudioAudio
	Director   StudioDirector
	Export     StudioExport
	Library    StudioLibrary
	Create     StudioCreate
	Clipper    StudioClipper
	TalkReel   StudioTalkReel
	Footage    StudioFootage
	Compiler   StudioCompiler
	Longcut    StudioLongcut
	Assets     StudioAssets
	Outputs    StudioOutputs
	Storyboard StudioStoryboard
	Cast       StudioCast
	Confirm    StudioConfirm
	Browse     StudioBrowse
	Collage    StudioCollage
	Paper      StudioPaper
}

// NewStudio creates a studio client. The API key is sent as a Bearer token.
func NewStudio(apiKey string, opts ...Option) *StudioClient {
	c := newClient("studio", "https://console.algohash.ai/mcp/studio", apiKey, StudioActionScopes, opts...)
	return &StudioClient{Client: c,
		Core:       StudioCore{c},
		Project:    StudioProject{c},
		Shots:      StudioShots{c},
		Layers:     StudioLayers{c},
		Audio:      StudioAudio{c},
		Director:   StudioDirector{c},
		Export:     StudioExport{c},
		Library:    StudioLibrary{c},
		Create:     StudioCreate{c},
		Clipper:    StudioClipper{c},
		TalkReel:   StudioTalkReel{c},
		Footage:    StudioFootage{c},
		Compiler:   StudioCompiler{c},
		Longcut:    StudioLongcut{c},
		Assets:     StudioAssets{c},
		Outputs:    StudioOutputs{c},
		Storyboard: StudioStoryboard{c},
		Cast:       StudioCast{c},
		Confirm:    StudioConfirm{c},
		Browse:     StudioBrowse{c},
		Collage:    StudioCollage{c},
		Paper:      StudioPaper{c},
	}
}
